require "test_helper"
require_relative "../test_helpers/session_test_helper"

# The backstage is behind the app's sign-in (generated by the maquina dashboard
# generators). Only a signed-in, unblocked user whose email is on the backstage
# list gets in; anyone else signed in gets a 404, so the pages never confirm
# they exist. The list lives in credentials (backstage.emails); these tests set
# config.x.backstage_emails, which User.backstage_emails reads first.
class BackstageAccessTest < ActionDispatch::IntegrationTest
  # The engine pages mounted under the backstage prefix, whichever are installed.
  PAGES = %w[errors jobs security].freeze

  setup do
    @emails_before = Rails.configuration.x.backstage_emails
    Rails.configuration.x.backstage_emails = [users(:backstage_operator).email_address]
  end

  teardown do
    Rails.configuration.x.backstage_emails = @emails_before
  end

  test "signed out, every backstage page asks to sign in" do
    # Before any request: after one into a mounted engine, URL helpers in an
    # integration test generate under that engine's mount point.
    sign_in = new_session_url

    backstage_paths.each do |path|
      get path

      assert_redirected_to sign_in, path
    end
  end

  test "a user not on the list gets not found on every backstage page" do
    sign_in_as users(:backstage_member)

    backstage_paths.each do |path|
      get path

      assert_response :not_found, path
    end
  end

  test "a blocked user on the list gets not found" do
    users(:backstage_operator).block!(reason: "test")
    sign_in_as users(:backstage_operator)

    get backstage_dashboard_path

    assert_response :not_found
  end

  test "an empty list lets nobody in" do
    Rails.configuration.x.backstage_emails = []
    sign_in_as users(:backstage_operator)

    get backstage_dashboard_path

    assert_response :not_found
  end

  test "a user on the list gets in" do
    sign_in_as users(:backstage_operator)

    get backstage_dashboard_path

    assert_response :success
  end

  private

  def backstage_paths
    mounted = Rails.application.routes.routes.map { |route| route.path.spec.to_s }
    pages = PAGES.map { |page| "#{backstage_dashboard_path}/#{page}" }.select { |path| mounted.any? { |spec| spec.start_with?(path) } }

    [backstage_dashboard_path, *pages]
  end
end
